-- =====================================================================
-- PulsePass - V1: esquema inicial (Fase 1 - Persistencia)
-- PRD Persistencia: secciones 6, 7, 8 y 15; BR-001 a BR-009; NFR-001.
--
-- Convenciones (decisiones aprobadas):
--   * Identificadores BIGINT GENERATED BY DEFAULT AS IDENTITY   (V1-1)
--   * Longitudes de texto: decisiones técnicas, no requisitos     (V1-2)
--   * Nombres de restricciones: pk_, fk_, uk_, ck_, ix_           (V1-9)
--   * Claves foráneas con ON DELETE NO ACTION                     (V1-10)
--   * Enums como VARCHAR(20) + CHECK con los valores del PRD      (V1-11, A9)
--   * Sin valores por defecto en la base de datos                 (V1-8)
--   * Índices explícitos solo en FK sin índice propio             (A10)
--
-- Fuera de V1: streaming_url (V3), datos iniciales (V2), seguridad (Fase 4).
-- =====================================================================


-- ---------------------------------------------------------------------
-- venues: sedes donde se realizan los eventos (FR-VEN-001..003)
-- ---------------------------------------------------------------------
CREATE TABLE venues (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY,
    code     VARCHAR(30)  NOT NULL,
    name     VARCHAR(150) NOT NULL,
    city     VARCHAR(100) NOT NULL,
    address  VARCHAR(200),                -- opcional (V1-3)
    capacity INTEGER      NOT NULL,
    active   BOOLEAN      NOT NULL,

    CONSTRAINT pk_venues          PRIMARY KEY (id),
    CONSTRAINT uk_venues_code     UNIQUE (code),                  -- FR-VEN-002
    CONSTRAINT ck_venues_capacity CHECK (capacity > 0)            -- FR-VEN-003
);


-- ---------------------------------------------------------------------
-- events: eventos; cada uno pertenece a exactamente un venue (BR-001)
-- ---------------------------------------------------------------------
CREATE TABLE events (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    event_code  VARCHAR(30)  NOT NULL,
    name        VARCHAR(150) NOT NULL,
    description VARCHAR(500),             -- opcional; 500 tomado del diseño frontend (V1-4)
    category    VARCHAR(20)  NOT NULL,
    status      VARCHAR(20)  NOT NULL,
    event_date  TIMESTAMP    NOT NULL,
    minimum_age INTEGER      NOT NULL,
    venue_id    BIGINT       NOT NULL,

    CONSTRAINT pk_events            PRIMARY KEY (id),
    CONSTRAINT uk_events_event_code UNIQUE (event_code),          -- FR-EVT-002
    CONSTRAINT ck_events_category   CHECK (category IN
        ('MUSIC', 'SPORTS', 'TECHNOLOGY', 'EDUCATION', 'CULTURE', 'ENTERTAINMENT')), -- FR-EVT-004
    CONSTRAINT ck_events_status     CHECK (status IN
        ('DRAFT', 'PUBLISHED', 'SOLD_OUT', 'CANCELLED', 'FINISHED')),                -- FR-EVT-003
    CONSTRAINT ck_events_minimum_age CHECK (minimum_age >= 0),    -- V1-7
    CONSTRAINT fk_events_venue      FOREIGN KEY (venue_id)
        REFERENCES venues (id) ON DELETE NO ACTION                -- BR-001, FR-EVT-001
);

CREATE INDEX ix_events_venue_id ON events (venue_id);             -- FR-VEN-004


-- ---------------------------------------------------------------------
-- artists: artistas que participan en eventos (FR-ART-001..002)
-- ---------------------------------------------------------------------
CREATE TABLE artists (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY,
    stage_name VARCHAR(150) NOT NULL,
    country    VARCHAR(100),              -- opcional (A8)
    genre      VARCHAR(100),              -- opcional (A8)
    active     BOOLEAN      NOT NULL,

    CONSTRAINT pk_artists            PRIMARY KEY (id),
    CONSTRAINT uk_artists_stage_name UNIQUE (stage_name)          -- FR-ART-002
);


-- ---------------------------------------------------------------------
-- event_artists: relación N:M entre events y artists (BR-003, sección 7)
-- La PK compuesta impide repetir el mismo par evento-artista (FR-ART-003).
-- ---------------------------------------------------------------------
CREATE TABLE event_artists (
    event_id  BIGINT NOT NULL,
    artist_id BIGINT NOT NULL,

    CONSTRAINT pk_event_artists        PRIMARY KEY (event_id, artist_id),
    CONSTRAINT fk_event_artists_event  FOREIGN KEY (event_id)
        REFERENCES events (id) ON DELETE NO ACTION,
    CONSTRAINT fk_event_artists_artist FOREIGN KEY (artist_id)
        REFERENCES artists (id) ON DELETE NO ACTION
);

-- La PK ya indexa (event_id, artist_id) empezando por event_id;
-- este índice cubre la búsqueda inversa por artista (FR-ART-004, FR-SRC-001).
CREATE INDEX ix_event_artists_artist_id ON event_artists (artist_id);


-- ---------------------------------------------------------------------
-- users: identidad de dominio del usuario (FR-USR-001..002, R-004)
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY,
    username VARCHAR(50)  NOT NULL,
    email    VARCHAR(254) NOT NULL,
    active   BOOLEAN      NOT NULL,

    CONSTRAINT pk_users          PRIMARY KEY (id),
    CONSTRAINT uk_users_username UNIQUE (username),               -- FR-USR-002
    CONSTRAINT uk_users_email    UNIQUE (email)                   -- FR-USR-002, A11
);


-- ---------------------------------------------------------------------
-- user_profiles: perfil individual, relación 1:1 con users (BR-004)
-- FK + UNIQUE sobre user_id garantiza un único perfil por usuario (FR-USR-003).
-- ---------------------------------------------------------------------
CREATE TABLE user_profiles (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY,
    first_name VARCHAR(100) NOT NULL,
    last_name  VARCHAR(100) NOT NULL,
    phone      VARCHAR(30),               -- opcional (V1-3)
    city       VARCHAR(100),              -- opcional (V1-3)
    birth_date DATE         NOT NULL,
    user_id    BIGINT       NOT NULL,

    CONSTRAINT pk_user_profiles         PRIMARY KEY (id),
    CONSTRAINT uk_user_profiles_user_id UNIQUE (user_id),         -- FR-USR-003 (1:1)
    CONSTRAINT fk_user_profiles_user    FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE NO ACTION
);


-- ---------------------------------------------------------------------
-- tickets: entidad propia con datos de la compra (BR-005, BR-006)
-- ---------------------------------------------------------------------
CREATE TABLE tickets (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    ticket_code   VARCHAR(30)    NOT NULL,
    type          VARCHAR(20)    NOT NULL,
    price         NUMERIC(12, 2) NOT NULL,  -- BigDecimal, nunca float/double (BR-007, NFR-008)
    status        VARCHAR(20)    NOT NULL,
    purchase_date TIMESTAMP,                -- admite NULL: un ticket RESERVED aún no se ha comprado (P1-D1)
    user_id       BIGINT         NOT NULL,
    event_id      BIGINT         NOT NULL,

    CONSTRAINT pk_tickets             PRIMARY KEY (id),
    CONSTRAINT uk_tickets_ticket_code UNIQUE (ticket_code),       -- FR-TKT-002
    CONSTRAINT ck_tickets_type        CHECK (type IN
        ('GENERAL', 'VIP', 'BACKSTAGE', 'STUDENT')),              -- FR-TKT-004
    CONSTRAINT ck_tickets_status      CHECK (status IN
        ('RESERVED', 'PAID', 'CANCELLED', 'USED')),               -- FR-TKT-005
    CONSTRAINT ck_tickets_price       CHECK (price >= 0),         -- FR-TKT-003
    CONSTRAINT fk_tickets_user        FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE NO ACTION,                -- FR-TKT-001
    CONSTRAINT fk_tickets_event       FOREIGN KEY (event_id)
        REFERENCES events (id) ON DELETE NO ACTION                -- FR-TKT-001
);

CREATE INDEX ix_tickets_user_id  ON tickets (user_id);            -- FR-TKT-006
CREATE INDEX ix_tickets_event_id ON tickets (event_id);           -- FR-TKT-007, FR-TKT-008
